-- Copyright (C) 2026 Alexandre Demartin
--
-- Reference schema for the characterization suite, loaded once per run into the
-- template database (test/helpers/globalSetup.ts).
--
-- Rules:
--   * Loads on Postgres 14, 16 and 18: no syntax newer than 14
--     (no NULLS NOT DISTINCT, no MERGE, no identity column on a partitioned table).
--   * Schema "edge" holds the cases that may break compilation of the generated
--     file (identifiers that are not TS identifiers, "*/" in comments or defaults,
--     quotes in enum labels). Codegen tests include it or not.
--   * Extensions live in schema "ext", so their functions stay out of "public".
--     "ext" is not on the search_path: citext operators need OPERATOR(ext.=).

SET client_min_messages = warning;

CREATE SCHEMA ext;
CREATE EXTENSION citext SCHEMA ext;
CREATE EXTENSION pg_trgm SCHEMA ext;
CREATE EXTENSION unaccent SCHEMA ext;
CREATE EXTENSION file_fdw SCHEMA ext;

CREATE SCHEMA extra;
CREATE SCHEMA edge;

COMMENT ON SCHEMA extra IS 'Second application schema: prefixed namespace in the generated file';

-- ---------------------------------------------------------------- types

CREATE TYPE public.mood AS ENUM ('sad', 'ok', 'happy');
CREATE TYPE extra.status AS ENUM ('draft', 'published', 'archived');

CREATE DOMAIN public.email AS ext.citext CHECK (VALUE LIKE '%_@_%');
CREATE DOMAIN public.positive_int AS integer CHECK (VALUE > 0);
CREATE DOMAIN public.tag_list AS text[] DEFAULT '{}';

CREATE TYPE public.address AS (street text, city text, zip varchar(10));
CREATE TYPE public.price AS (amount numeric(12, 2), currency char(3));

CREATE TYPE public.float_range AS RANGE (subtype = float8);

COMMENT ON TYPE public.mood IS 'How a user feels';
COMMENT ON DOMAIN public.email IS 'Case-insensitive e-mail address';

-- ---------------------------------------------------------------- tables

CREATE TABLE public.users (
  id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email public.email NOT NULL UNIQUE,
  display_name text NOT NULL,
  mood public.mood,
  manager_id int REFERENCES public.users (id),  -- self-referencing FK
  home public.address,
  settings jsonb NOT NULL DEFAULT '{}',
  tags public.tag_list,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.users IS 'People who can sign in';
COMMENT ON COLUMN public.users.manager_id IS 'Line manager.
Nullable: the top of the tree has none.';

CREATE TABLE public.accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_id int NOT NULL REFERENCES public.users (id) ON DELETE CASCADE,
  balance numeric(14, 2) NOT NULL DEFAULT 0,
  overdraft_limit public.positive_int,
  lifetime_ops int8 NOT NULL DEFAULT 0,
  ratio float8,
  scores int4[] NOT NULL DEFAULT '{}',
  flags bool[],
  grid int[][],
  opened_on date NOT NULL DEFAULT current_date
);

-- composite primary key, referenced by a composite FK
CREATE TABLE public.orgs (
  country char(2) NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  parent_country char(2),
  parent_code text,
  PRIMARY KEY (country, code),
  FOREIGN KEY (parent_country, parent_code) REFERENCES public.orgs (country, code)  -- composite self-reference
);

CREATE TABLE public.memberships (
  user_id int NOT NULL REFERENCES public.users (id),
  org_country char(2) NOT NULL,
  org_code text NOT NULL,
  role text NOT NULL DEFAULT 'member',
  since timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, org_country, org_code),
  FOREIGN KEY (org_country, org_code) REFERENCES public.orgs (country, code)
);

-- two FKs to the same table, ranges, uuid default
CREATE TABLE public.transfers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  from_account bigint NOT NULL REFERENCES public.accounts (id),
  to_account bigint NOT NULL REFERENCES public.accounts (id),
  amount numeric NOT NULL CHECK (amount > 0),
  valid_during tstzrange,
  value_days daterange,
  batch_sizes int4range,
  fee_band numrange,
  note text,
  CHECK (from_account <> to_account)
);

-- generated columns, multi-column unique constraint and unique indexes
CREATE TABLE public.products (
  id serial PRIMARY KEY,
  sku text NOT NULL,
  variant text NOT NULL DEFAULT '',
  title text,
  list_price public.price,
  price_cents int8 NOT NULL,
  vat_rate numeric(5, 4) NOT NULL DEFAULT 0.2,
  price_with_vat_cents numeric GENERATED ALWAYS AS (price_cents * (1 + vat_rate)) STORED,
  search tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(title, ''))) STORED,
  weight_kg public.float_range,
  status extra.status NOT NULL DEFAULT 'draft',
  UNIQUE (sku, variant)
);

CREATE UNIQUE INDEX products_title_lower_key ON public.products (lower(title)) WHERE title IS NOT NULL;
CREATE UNIQUE INDEX products_status_sku_key ON public.products (status, sku, variant);
CREATE INDEX products_title_trgm ON public.products USING gin (title ext.gin_trgm_ops);

-- quoted identifiers that are still legal TS identifiers, or quoted by the codegen
CREATE TABLE public."OrderLines" (
  "orderId" bigint NOT NULL,
  "lineNo" int NOT NULL,
  "Product Id" int NOT NULL REFERENCES public.products (id),
  "select" text,
  "unit-price" numeric(10, 2) NOT NULL,
  PRIMARY KEY ("orderId", "lineNo")
);

-- partitioned table
CREATE TABLE public.events (
  id bigserial,
  occurred_on date NOT NULL,
  kind text NOT NULL,
  payload jsonb,
  PRIMARY KEY (id, occurred_on)
) PARTITION BY RANGE (occurred_on);

CREATE TABLE public.events_2025 PARTITION OF public.events FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE TABLE public.events_2026 PARTITION OF public.events FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE public.events_default PARTITION OF public.events DEFAULT;

-- one column per scalar type the codegen maps
CREATE TABLE extra.type_zoo (
  id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  c_int2 int2, c_int4 int4, c_int8 int8, c_numeric numeric, c_float4 float4, c_float8 float8, c_money money,
  c_bool bool, c_text text, c_varchar varchar(20), c_char char(4), c_citext ext.citext, c_name name,
  c_bytea bytea, c_uuid uuid, c_json json, c_jsonb jsonb, c_xml xml,
  c_date date, c_time time, c_timetz timetz, c_timestamp timestamp, c_timestamptz timestamptz, c_interval interval,
  c_inet inet, c_cidr cidr, c_macaddr macaddr, c_bit bit(3), c_varbit varbit, c_tsvector tsvector, c_tsquery tsquery,
  c_point point, c_oid oid, c_int4multirange int4multirange,
  c_text_array text[], c_jsonb_array jsonb[], c_uuid_array uuid[], c_date_array date[], c_enum_array public.mood[]
);

CREATE TABLE extra.articles (
  id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  author_id int NOT NULL REFERENCES public.users (id),
  reviewer_id int REFERENCES public.users (id),
  status extra.status NOT NULL DEFAULT 'draft',
  body text NOT NULL
);

-- foreign table (file_fdw): /dev/null exists on every server, so scans return no row
CREATE SERVER fixture_files FOREIGN DATA WRAPPER file_fdw;
CREATE FOREIGN TABLE extra.imported_lines (line text) SERVER fixture_files OPTIONS (filename '/dev/null', format 'text');

-- ---------------------------------------------------------------- views

CREATE VIEW public.active_users AS
  SELECT id, email, display_name, mood FROM public.users WHERE mood IS DISTINCT FROM 'sad';

CREATE VIEW extra.article_authors AS
  SELECT a.id AS article_id, a.status, u.display_name AS author
  FROM extra.articles a JOIN public.users u ON u.id = a.author_id;

CREATE MATERIALIZED VIEW public.account_totals AS
  SELECT owner_id, count(*) AS account_count, sum(balance) AS total_balance
  FROM public.accounts GROUP BY owner_id;

CREATE UNIQUE INDEX account_totals_owner_key ON public.account_totals (owner_id);

COMMENT ON VIEW public.active_users IS 'Users not currently sad';
COMMENT ON MATERIALIZED VIEW public.account_totals IS 'Balances per owner, refreshed on demand';

-- ---------------------------------------------------------------- functions

CREATE FUNCTION public.full_name(first text, last text) RETURNS text
  LANGUAGE sql IMMUTABLE AS $$ SELECT first || ' ' || last $$;

CREATE FUNCTION public.account_balance(account bigint) RETURNS numeric
  LANGUAGE plpgsql STABLE AS $$
BEGIN
  RETURN (SELECT balance FROM public.accounts WHERE id = account);
END
$$;

CREATE FUNCTION public.reports_of(manager int) RETURNS SETOF public.users
  LANGUAGE sql STABLE AS $$ SELECT * FROM public.users WHERE manager_id = manager $$;

CREATE FUNCTION extra.transfer_totals(since timestamptz DEFAULT '-infinity')
  RETURNS TABLE (account_id bigint, sent numeric, received numeric)
  LANGUAGE plpgsql STABLE AS $$
BEGIN
  RETURN QUERY
    SELECT a.id,
      coalesce((SELECT sum(t.amount) FROM public.transfers t WHERE t.from_account = a.id
        AND coalesce(lower(t.valid_during), 'infinity') >= since), 0),
      coalesce((SELECT sum(t.amount) FROM public.transfers t WHERE t.to_account = a.id
        AND coalesce(lower(t.valid_during), 'infinity') >= since), 0)
    FROM public.accounts a ORDER BY a.id;
END
$$;

CREATE FUNCTION public.split_email(address text, OUT local_part text, OUT domain text)
  LANGUAGE sql IMMUTABLE AS $$ SELECT split_part(address, '@', 1), split_part(address, '@', 2) $$;

CREATE FUNCTION public.sum_all(VARIADIC nums int[]) RETURNS int
  LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(sum(n), 0)::int FROM unnest(nums) n $$;

-- overloads
CREATE FUNCTION public.describe(x int) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT 'int ' || x $$;
CREATE FUNCTION public.describe(x text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT 'text ' || x $$;
CREATE FUNCTION public.describe(x int, y int) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT 'pair ' || x || ',' || y $$;

CREATE FUNCTION extra.search_key(input text) RETURNS text
  LANGUAGE sql STABLE AS $$ SELECT lower(ext.unaccent(input)) $$;

CREATE PROCEDURE public.cheer_up(who int)
  LANGUAGE plpgsql AS $$
BEGIN
  UPDATE public.users SET mood = 'happy' WHERE id = who;
END
$$;

COMMENT ON FUNCTION public.reports_of(int) IS 'Direct reports of a manager';

-- ---------------------------------------------------------------- codegen suspects

-- column comments on relations that are not plain tables
COMMENT ON COLUMN public.events.kind IS 'Partitioned table column comment';
COMMENT ON COLUMN extra.imported_lines.line IS 'Foreign table column comment';
COMMENT ON COLUMN public.active_users.display_name IS 'View column comment';
COMMENT ON COLUMN public.account_totals.total_balance IS 'Materialized view column comment';

-- one index name in two schemas: unique on extra.articles, not unique on public.transfers
CREATE UNIQUE INDEX shared_name_idx ON extra.articles (body);
CREATE INDEX shared_name_idx ON public.transfers (note);

-- ---------------------------------------------------------------- edge: may break the generated file

CREATE TYPE edge."traffic-light" AS ENUM ('red', 'amber''s', 'green light');

CREATE TABLE edge."odd table" (
  id int PRIMARY KEY,
  light edge."traffic-light",
  "*/" text DEFAULT '*/',
  "class" text
);

CREATE TABLE edge.class (
  id int PRIMARY KEY
);

COMMENT ON TABLE edge."odd table" IS 'Comment that closes a JSDoc block: */ and keeps going';
COMMENT ON COLUMN edge."odd table".light IS 'Column comment with */ inside';

